import React, { useState, useRef, useImperativeHandle, forwardRef } from 'react';
import { Project } from '../types';
import { SectionLabel } from './Primitives';
import { Flow } from 'flow-sdk';

export const CoverDesigner = forwardRef<{ exportCover: () => Promise<void> }, { project: Project; updateProject: (u: any) => void }>(({ project, updateProject }, ref) => {
  const [exporting, setExporting] = useState(false);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const handleDownloadFullCover = async () => {
    if (!project.cover.fullWrapBase64 && (!project.cover.frontBase64 || !project.cover.backBase64)) {
      alert("Please generate a cover wrap first using the sidebar.");
      return;
    }

    setExporting(true);
    const canvas = canvasRef.current!;
    const ctx = canvas.getContext('2d')!;

    const DPI = 300;
    const bleed = 0.125 * DPI;
    const sideWidth = 6 * DPI;
    const sideHeight = 9 * DPI;
    const spineWidth = project.cover.spineWidthInches * DPI;

    const totalWidth = sideWidth + sideWidth + spineWidth + (bleed * 2);
    const totalHeight = sideHeight + (bleed * 2);

    canvas.width = totalWidth;
    canvas.height = totalHeight;

    const loadImage = (base64: string): Promise<HTMLImageElement> => {
      return new Promise((resolve) => {
        const img = new Image();
        img.onload = () => resolve(img);
        img.src = `data:image/png;base64,${base64}`;
      });
    };

    try {
      if (project.cover.fullWrapBase64) {
        const wrap = await loadImage(project.cover.fullWrapBase64);
        ctx.drawImage(wrap, 0, 0, totalWidth, totalHeight);
      } else {
        const backImg = await loadImage(project.cover.backBase64);
        const frontImg = await loadImage(project.cover.frontBase64);
        ctx.fillStyle = '#000000';
        ctx.fillRect(0, 0, totalWidth, totalHeight);
        ctx.drawImage(backImg, bleed, bleed, sideWidth, sideHeight);
        ctx.drawImage(frontImg, bleed + sideWidth + spineWidth, bleed, sideWidth, sideHeight);
        ctx.fillStyle = '#111111';
        ctx.fillRect(bleed + sideWidth, bleed, spineWidth, sideHeight);
      }

      // Mandatory Spine Text Overlay
      ctx.save();
      ctx.translate(bleed + sideWidth + (spineWidth / 2), totalHeight / 2);
      ctx.rotate(Math.PI / 2);
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = 'white';
      ctx.shadowColor = 'rgba(0,0,0,0.5)';
      ctx.shadowBlur = 10;
      ctx.font = `bold ${Math.max(24, spineWidth * 0.4)}px "Google Sans Text"`;
      ctx.fillText(`${project.name.toUpperCase()}  |  ${project.author.toUpperCase()}`, 0, 0);
      ctx.restore();

      const base64 = canvas.toDataURL('image/png').split(',')[1];
      await Flow.download({
        base64,
        mimeType: 'image/png',
        filename: `KDP_FULL_WRAP_${project.name.replace(/\s+/g, '_')}.png`
      });
    } catch (e) {
      console.error("Export failed", e);
    } finally {
      setExporting(false);
    }
  };

  useImperativeHandle(ref, () => ({
    exportCover: handleDownloadFullCover
  }));

  return (
    <div className="flex flex-col gap-10 w-full max-w-6xl animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="flex justify-between items-end">
        <div>
          <h2 className="text-3xl font-bold">Paperback Wrap Designer</h2>
          <p className="text-white/40 text-sm italic">Matched Front & Back • 6x9" Standard Format • Auto-spine: {project.cover.spineWidthInches.toFixed(3)}"</p>
        </div>
        {exporting && (
          <div className="flex items-center gap-2 text-[12px] text-[#969696] animate-pulse">
            <span className="material-symbols-outlined animate-spin">refresh</span>
            Stitching high-res wrap...
          </div>
        )}
      </div>

      <div className="relative flex flex-col gap-1 items-center justify-center p-8 bg-[#0a0a0a] border border-white/5 rounded-[40px] shadow-2xl overflow-hidden min-h-[500px]">
        {project.cover.fullWrapBase64 ? (
          <div className="relative w-full aspect-[16/9] rounded-2xl overflow-hidden border border-white/10 group">
            <img src={`data:image/png;base64,${project.cover.fullWrapBase64}`} className="w-full h-full object-cover" alt="Full Wrap" />

            {/* Guide Overlays for Preview */}
            <div className="absolute inset-0 flex">
               <div className="flex-1 bg-black/10 border-r border-white/20 flex items-center justify-center">
                  <span className="text-[10px] font-bold text-white/20 uppercase tracking-widest rotate-[-90deg]">Back Cover</span>
               </div>
               <div className="w-8 bg-black/40 border-x border-white/30 flex items-center justify-center overflow-hidden">
                  <span className="text-[8px] font-bold text-white/60 uppercase tracking-widest rotate-[-90deg] whitespace-nowrap">{project.name}</span>
               </div>
               <div className="flex-1 bg-black/10 flex items-center justify-center">
                  <span className="text-[10px] font-bold text-white/20 uppercase tracking-widest rotate-[-90deg]">Front Cover</span>
               </div>
            </div>
          </div>
        ) : (
          <div className="flex flex-col items-center gap-4 text-white/10 py-20">
             <span className="material-symbols-outlined text-[80px]">auto_stories</span>
             <p className="text-[12px] font-bold uppercase tracking-[0.3em]">Generate Unified Wrap in Sidebar</p>
          </div>
        )}
      </div>

      <canvas ref={canvasRef} className="hidden" />

      <div className="grid grid-cols-2 gap-4">
        <div className="p-4 bg-white/5 rounded-2xl border border-white/10 flex items-center gap-3">
          <span className="material-symbols-outlined text-cyan-500/50">style</span>
          <p className="text-[11px] text-white/60 leading-relaxed">
            <strong>Visual Matching:</strong> Unified wrap generation treats front, back, and spine as a single artistic canvas, ensuring color and lighting continuity.
          </p>
        </div>
        <div className="p-4 bg-white/5 rounded-2xl border border-white/10 flex items-center gap-3">
          <span className="material-symbols-outlined text-[#969696]/50">lock</span>
          <p className="text-[11px] text-white/60 leading-relaxed">
            <strong>Character Consistency:</strong> Your locked character references are automatically used when generating the cover art.
          </p>
        </div>
      </div>
    </div>
  );
});

